 1 | // SPDX-License-Identifier: GPL-3.0
 2 | pragma solidity 0.8.17;
 3 | 
 4 | import "../party/Party.sol";
 5 | 
 6 | /// @notice A contract that allows members of a party that has this contract as
 7 | ///         a host to vote to veto a proposal.
 8 | contract VetoProposal {
 9 |     error NotPartyHostError();
10 |     error ProposalNotActiveError(uint256 proposalId);
11 | 
12 |     /// @notice Mapping from party to proposal ID to votes to veto the proposal.
13 |     mapping(Party => mapping(uint256 => uint96)) public vetoVotes;
14 | 
15 |     /// @notice Vote to veto a proposal.
16 |     /// @param party The party to vote on.
17 |     /// @param proposalId The ID of the proposal to veto.
18 |     /// @param snapIndex The index of the snapshot to use for voting power.
19 |     function voteToVeto(Party party, uint256 proposalId, uint256 snapIndex) external {
20 |         uint96 votes = vetoVotes[party][proposalId];
21 | 
22 |         // No need to perform following check more than once for party
23 |         if (votes == 0) {
24 |             // Check if this contract is a host of the party
25 |             if (!party.isHost(address(this))) revert NotPartyHostError();
26 |         }
27 | 
28 |         // Check that proposal is active
29 |         (
30 |             PartyGovernance.ProposalStatus proposalStatus,
31 |             PartyGovernance.ProposalStateValues memory proposalValues
32 |         ) = party.getProposalStateInfo(proposalId);
33 |         if (proposalStatus != PartyGovernance.ProposalStatus.Voting)
34 |             revert ProposalNotActiveError(proposalId);
35 | 
36 |         // Increase the veto vote count
37 |         uint96 votingPower = party.getVotingPowerAt(
38 |             msg.sender,
39 |             proposalValues.proposedTime - 1,
40 |             snapIndex
41 |         );
42 |         uint96 newVotes = votes + votingPower;
43 | 
44 |         // Check if the vote to veto is passing
45 |         PartyGovernance.GovernanceValues memory governanceValues = party.getGovernanceValues();
46 |         if (
47 |             _areVotesPassing(
48 |                 newVotes,
49 |                 governanceValues.totalVotingPower,
50 |                 governanceValues.passThresholdBps
51 |             )
52 |         ) {
